{
 "id": "GAP-16",
 "key": "g2:monolith_defect:register_check_then_put_race",
 "category": "monolith_defect",
 "summary": "POST /api/auth/register 判重是“先 Query email-index、再 Put 新用户”，两步之间没有条件写也没有事务（routes/auth.js:56,58,81）：并发用同一邮箱注册可以双双通过判重，写出两条 email 相同、userId 不同的条目；此后 POST /api/auth/login 只取 result.Items[0]（routes/auth.js:137），登录命中哪个账号取决于索引返回顺序。判重用的 Query 还是默认最终一致性读，刚注册的账号在短暂窗口内可能查不到，使重复窗口比单纯并发更宽。",
 "evidence": [
  {
   "file": "bookstore/routes/auth.js",
   "line": 56,
   "symbol": "const existingUser = await docClient.query(checkParams).promise();"
  },
  {
   "file": "bookstore/routes/auth.js",
   "line": 58,
   "symbol": "existingUser.Items.length > 0"
  },
  {
   "file": "bookstore/routes/auth.js",
   "line": 81,
   "symbol": "await docClient.put(params).promise();"
  },
  {
   "file": "bookstore/routes/auth.js",
   "line": 137,
   "symbol": "const user = result.Items[0];"
  }
 ],
 "endpoints": [
  "POST /api/auth/register",
  "POST /api/auth/login"
 ],
 "source": "G2",
 "status": "open"
}
